const competitors = $("Load Competitors").all().map(i => i.json);
const cfgRow = $("Load SOV Config").first();
const config = (cfgRow && cfgRow.json && cfgRow.json.config) ? cfgRow.json.config : {};
const active = competitors.filter(c => c.active !== false);
const companies = active.map(c => ({ name: c.name, aliases: Array.isArray(c.aliases) ? c.aliases : [], domain: c.domain || null, x_handle: c.x_handle || null, linkedin_urn: c.linkedin_urn || null, subreddits: Array.isArray(c.subreddits) ? c.subreddits : [], type: c.type || 'direct' }));
const linkedin_urns = companies.map(c => c.linkedin_urn).filter(Boolean);
const companyEnum = companies.map(c => c.name).join(", ");
const allSubreddits = Array.from(new Set([].concat(...companies.map(c => c.subreddits)).concat(["cybersecurity","netsec","asknetsec","devsecops","hacking","information_security","security","identitymanagement","sysadmin","itmanagers","blueteamsec"]))).filter(Boolean);
return [{ json: { config, companies, linkedin_urns, companyEnum, allSubreddits } }];

const ctx = $('Build Context').first().json;
const config = ctx.config || {};
const companies = (ctx.companies || []).filter(c => c && c.name);
const companyEnum = ctx.companyEnum || '';
// Per-company LinkedIn search keyword overrides (specific names cut generic-word junk -> cheaper Apify).
// Default = the full company name. Opti gets TWO queries. (Console provisional: confirm.)
const KW = { 'Lumos': ['Lumos'], 'Opti': ['Opti IAM','Opti Identity'], 'OFFROAD': ['Offroad Security'], '7AI': ['7AI'], 'Console': ['Console security'] };
const out = [];
for (const c of companies) {
  const kws = KW[c.name] || [String(c.name)];
  for (const kw of kws) {
    out.push({ json: { name: c.name, keyword: kw, aliases: c.aliases || [], linkedin_urn: c.linkedin_urn || '', type: c.type || 'direct', config: config, companies: companies, companyEnum: companyEnum } });
  }
}
return out;

const needs = $("Filter Needs URN").all().map(i => i.json);
function norm(u){ return String(u||"").trim().toLowerCase().replace(/\/+$/,""); }
function slugFromUrl(u){ const m = norm(u).match(/\/company\/([^\/?#]+)/); return m ? m[1] : null; }
function looksSlugDerived(name, slug){
  const n = String(name||"").trim();
  if (!n) return true; // missing
  if (slug) {
    const slugWords = slug.replace(/-/g, ' ').toLowerCase().trim();
    if (n.toLowerCase() === slug.toLowerCase()) return true; // exact slug
    if (n.toLowerCase() === slugWords) return true; // hyphen-stripped slug
  }
  // heuristic: a real display name usually has a space or capital letter; pure lowercase single token = slug-ish
  if (!/\s/.test(n) && n === n.toLowerCase() && /[-_]/.test(n)) return true;
  return false;
}
function extractDomain(r){
  const bi = r.basic_info || {};
  const cand = r.website || r.domain || bi.website || bi.domain || (bi.websites && bi.websites[0]) || null;
  if (!cand) return null;
  try { const u = new URL(String(cand).match(/^https?:\/\//) ? cand : ('https://' + cand)); return u.hostname.replace(/^www\./, '').toLowerCase(); } catch(e) { return String(cand).replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].toLowerCase() || null; }
}
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const bi = r.basic_info || {};
  const urn = r.company_urn || bi.company_urn || null;
  if (!urn) continue;
  const ident = norm(r.input_identifier);
  const slug = bi.universal_name ? norm(bi.universal_name) : null;
  let comp = needs.find(c => norm(c.linkedin_url) === ident);
  if (!comp && slug) comp = needs.find(c => slugFromUrl(c.linkedin_url) === slug);
  if (!comp && ident) comp = needs.find(c => norm(c.linkedin_url).indexOf(ident) !== -1 || ident.indexOf(norm(c.linkedin_url)) !== -1);
  if (!comp) continue;
  const urlSlug = slug || slugFromUrl(comp.linkedin_url);
  const actorName = (bi.name && String(bi.name).trim()) ? String(bi.name).trim() : null;
  const actorDomain = extractDomain(r);
  // Only override name when current is missing/slug-derived and we have a real actor name
  const finalName = (actorName && looksSlugDerived(comp.name, urlSlug)) ? actorName : comp.name;
  // Only set domain when current is missing/empty and actor gave one
  const currentDomain = (comp.domain && String(comp.domain).trim()) ? String(comp.domain).trim().toLowerCase().replace(/^www\./,'') : null;
  const finalDomain = currentDomain || actorDomain || null;
  out.push({ json: { name: finalName, match_url: comp.linkedin_url, linkedin_url: comp.linkedin_url, linkedin_urn: String(urn), domain: finalDomain } });
}
return out;
